  ('ict-lec-ch05-mcq-312', 'class9-ict-bn-guide', 'ict-lecture-satt', 'গ্রেডিয়েন্ট টুল সিলেক্ট করে মাউস ক্যানভাসে নিয়ে এলে কোন চিহ্নে পরিণত iii. ছবি ফেটে যাবে হবে? নিচের কোনটি সঠিক? (জ্ঞান) (অনুধাবন)', 'mcq', '{"ক":"গুণ","খ":"i ওiii ভাগ ● যোগ","গ":"ii ওiii ii ওiii","ঘ":"ডাস্টার i. ব্যানারে নিচের কোনটি সঠিক? (অনুধাবন)"}'::jsonb, 'ঘ', null, 1, null, 'mcq_bank', null, 5, false),
