  ('ict-lec-ch05-mcq-497', 'class9-ict-bn-guide', 'ict-lecture-satt', 'মাল্টিমিডিয়ার ব্যবহার করা হয় সম্পকের্ কী কী দেখাবেন। একাজে তিনি কোনটিতে? একটি সফটওয়্যারের সাহায্য নিলেন।', 'mcq', '{"ক":"বিদ্যালয়ের ফলাফল প্রস্তুতিতে","খ":"বাজারের হিসাব করতে উপস্থাপনের জন্য রকিব সাহেবের জন্য","গ":"ক্রিকেট খেলার রান হিসাব করতে কোন সফটওয়্যারটি ব্যবহার","ঘ":"অ্যানিমেশন চলচ্চিত্র তৈরিতে myweavRbK?"}'::jsonb, 'ঘ', null, 1, null, 'mcq_bank', null, 5, false),
